// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2014, "4-5", [{"author":"Л. Фёдорова","question":"Какое выражение вряд ли встретится в первом предложении сказки?","choices":["<em>в некотором царстве</em>","<em>жили-были</em>","<em>жила-была</em>","<em>жил-был</em>","<em>жить-поживать</em>."],"key":"Д","review":["Начало сказки","В начале сказки знакомят с героями и местом. Для этого подходят «в некотором царстве» и формы «жил-был», «жила-была» и «жили-были».","«Стали жить-поживать» говорят в конце истории, когда приключения позади. Поэтому «жить-поживать» в начале вряд ли встретится."]},{"author":"Б. Иомдин","question":"Значения первого мы ищем во втором. Первое и второе ― это:","choices":["<em>государство</em> и <em>государь</em>","<em>глава</em> и <em>главарь</em>","<em>слово</em> и <em>словарь</em>","<em>секрет</em> и <em>секретарь</em>","<em>песок</em> и <em>пескарь</em>."],"key":"В","review":["Где найти значение","Вспомни, что выясняют, когда встречают незнакомое слово. Хочется узнать, что оно значит.","Значения слов собраны в толковом словаре. Пара получается «слово и словарь»."]},{"author":"И. Иткин и Е. Ренковская","question":"Узнав, что папа собирается в магазин, Костя составил для него список важных покупок:\n1) <em>наколенники для катания на роликах</em>; 2) <em>наушники для плеера</em>;\n3) <em>намордник для Шарика</em>; 4) <em>нашейник для Шарика</em>.\nВ каком пункте списка Костя ошибся?","choices":["только в 1","только в 2","только в 3","только в 4","в 3 и 4."],"key":"Г","review":["Покупки для Шарика","Наколенники защищают колени, наушники надевают на уши, а собаке можно купить намордник. Эти три названия верны.","То, что надевают собаке на шею, называют ошейником. В четвёртом пункте Костя придумал «нашейник» по образцу остальных слов."]},{"author":"Е. Муравенко","question":"Как обычно не говорят о времени?","choices":["<em>приходит</em>","<em>идёт</em>","<em>бежит</em>","<em>летит</em>","<em>прыгает</em>."],"key":"Д","review":["Что делает время","Проверь привычные выражения. Приходит время делать уроки, время идёт, бежит или летит, когда проходит быстро.","«Время прыгает» в обычной речи не говорят. Из предложенных глаголов «прыгает» стоит отдельно."]},{"author":"Л. Фёдорова","question":"В Королевстве кривых зеркал, куда попала Оля, у неё оказалась подружка Яло — её ожившее отражение. Оля записала под диктовку Яло имена жителей этого королевства. Одну запись Яло сочла нужным исправить; какую?","choices":["<em>Абаж</em>","<em>Аксал</em>","<em>Асырк</em>","<em>Нушрок</em>","<em>Ягупоп</em>."],"key":"Д","review":["Записи Яло","Прочитай каждое имя справа налево. «Абаж», «Аксал», «Асырк» и «Нушрок» превращаются в «жаба», «ласка», «крыса», «коршун».","«Ягупоп» даёт «попугя». Чтобы получить «попугай», нужно было записать «Йагупоп»."]},{"author":"Б. Иомдин","question":"Какого слова не существует?","choices":["<em>мил</em>","<em>мыл</em>","<em>мылы</em>","<em>милы</em>","<em>мыли</em>."],"key":"В","review":["Похожие формы","Скажи «он мил, они милы» и «он мыл, они мыли». Эти формы описывают качество или действие.","«Мылы» не подходит ни к прилагательному «милый», ни к глаголу «мыть». Даже разные сорта мыла называют «мыла», с а на конце."]},{"author":"Е. Кац","question":"Саша и Маша складывали птичек из бумаги. Саша сделал птичке изогнутый клюв и сказал: «Вот, смотри, как он сильно ...!» Какое слово должно стоять на месте пропуска?","choices":["<em>изгибнулся</em>","<em>изогнулся</em>","<em>изгнулся</em>","<em>загибнулся</em>","<em>загинулся</em>."],"key":"Б","review":["Бумажный клюв","Найди связь между словом «изогнутый» и глаголом, обозначающим, что клюв стал кривым.","Глагол «изогнуться» в прошедшем времени даёт «изогнулся». На часть «изог-» указывает и слово «изогнутый»."]},{"author":"М. Рубинштейн","question":"Несколько лет назад по телевидению шёл российский сериал о жизни будущих врачей — студентов-медиков. Он назывался … .","choices":["«Я прилечу»","«Я улетел»","«Я лечу»","«Я летаю»","«Мы летим»."],"key":"В","review":["Сериал о студентах","Вспомни, что делают врачи. Они лечат больных, а от первого лица можно сказать «я лечу».","«Я лечу» также можно сказать про полёт. Это название обыгрывает совпадение форм глаголов «лечить» и «лететь»."]},{"author":"Л. Фёдорова","question":"Многих птиц можно назвать обычным именем или ласково: <em>воробей — воробушек</em>. А какая птица имеет только «ласковое» имя?","choices":["галка","синица","скворец","ласточка","соловей."],"key":"Г","review":["Имена птиц","Сравни «воробей — воробушек» с другими названиями. «Галка», «синица», «скворец», «соловей» — обычные названия, для которых можно подобрать ласковые формы.","У «ласточки» звучит ласковое «-очк-», но это уже основное название птицы. В обычной речи самостоятельного имени «ласта» для неё нет."]},{"author":"В. Антонюк","question":"Сколько букв алфавита идёт подряд в названии детской телепередачи «АБВГДейка»?","choices":["три","четыре","пять","шесть","семь."],"key":"Г","review":["Буквы в названии","Двигайся по алфавиту от А. В названии сразу видны А, Б, В, Г, Д. Проверь и следующую букву, даже если она строчная.","Следом стоит е, шестая буква. Дальше по алфавиту ждёшь ё, но напечатана й. Подряд идут шесть букв."]},{"author":"Л. Фёдорова","question":"В сказке Л. Лагина «Старик Хоттабыч» один из главных героев ― арабский маг и волшебник Гасан Абдуррахман ибн Хоттаб. Что значит «ибн» по-арабски?","choices":["из рода","внук","дед","отец","сын."],"key":"Д","review":["Имя Хоттабыча","В полном имени волшебника за «ибн» стоит Хоттаб. В русском прозвище «Хоттабыч» та же часть выглядит как отчество.","В отчестве называют отца: Хоттабыч — сын Хоттаба. Поэтому «ибн Хоттаб» значит «сын Хоттаба»."]},{"author":"Л. Фёдорова","question":"Названия птиц иногда достаточно ясно указывают на их свойства. А какое из перечисленных названий указывает на происхождение птицы?","choices":["<em>снегирь</em>","<em>зяблик</em>","<em>индейка</em>","<em>кукушка</em>","<em>малиновка</em>."],"key":"В","review":["Откуда имя птицы","Снегирь напоминает о снеге, зяблик — о зябкости, кукушка — о крике «ку-ку», малиновка — о малиновом цвете.","Название «индейка» связано со словом «индеец». Так европейцы называли коренных жителей Америки, откуда в Европу привезли этих птиц. Здесь название указывает на происхождение."]},{"author":"Н. Добрушина","question":"В книге Ирины и Леонида Тюхтяевых «Зоки и бада» зоки жалуются: «Ты, бада, нас не любишь, тебе для нас даже той буреточки жалко». Чего бада не дал зокам?","choices":["<em>тубареточки</em>","<em>тобуреточки</em>","<em>тойбуреточки</em>","<em>табуреточки</em>","<em>тубуреточки</em>."],"key":"Г","review":["На что жалуются зоки","Произнеси «той буреточки» слитно. Зоки разделили на два слова знакомое название маленького сиденья без спинки.","Это «табуреточка», уменьшительное от «табурет». В вопросе «чего не дал?» нужна форма «табуреточки»."]},{"author":"В. Антонюк","question":"В мультфильме по сказочной повести Э. Успенского крокодил Гена пытается найти в энциклопедии на букву <strong><em>ч</em></strong> слово <em>Чебурашка</em>. В каком порядке должны были бы идти найденные им слова, если бы слово <em>Чебурашка</em> действительно обнаружилось в энциклопедии?","choices":["<em>чай</em>, <em>чемодан</em>, <em>чебурек</em>, <em>Чебурашка</em>, <em>Чебоксары</em>","<em>чай</em>, <em>чебурек</em>, <em>Чебурашка</em>, <em>Чебоксары</em>, <em>чемодан</em>","<em>чай</em>, <em>Чебоксары</em>, <em>Чебурашка</em>, <em>чебурек</em>, <em>чемодан</em>","<em>чай</em>, <em>Чебурашка</em>, <em>чебурек</em>, <em>Чебоксары</em>, <em>чемодан</em>","<em>Чебоксары</em>, <em>Чебурашка</em>, <em>чебурек</em>, <em>чемодан</em>, <em>чай</em>."],"key":"В","review":["Слова в энциклопедии","Сравни буквы после Ч. В «чай» вторая буква А, а у остальных Е, поэтому «чай» идёт первым. Среди слов с «че» буква Б предшествует М.","У «Чебоксары» после «чеб» стоит О, у двух оставшихся — У. После «чебур» А идёт раньше Е, так что порядок: чай, Чебоксары, Чебурашка, чебурек, чемодан."]},{"author":"И. Иткин","question":"В польском языке: chleb ― <em>хлеб</em>, ucho ― <em>ухо</em>, ryba ― <em>рыба</em>, dym ― <em>дым</em>. Как переводится на русский язык с польского слово mucha?","choices":["<em>мох</em>","<em>муха</em>","<em>молча</em>","<em>мышка</em>","<em>мычать</em>."],"key":"Б","review":["Польское слово","В парах chleb — хлеб и ucho — ухо две буквы ch обозначают русский звук [х]. Найди их в слове mucha.","Если прочитать ch как х, а остальные буквы как м, у и а, получится «муха»."]},{"author":"Б. Иомдин","question":"<em>Мне нужны такие вещи:</em>\n<em>Молоток, тиски и клещи,</em>\n<em>Ключ, напильник и ножовка,</em>\n<em>А всего нужней ― сноровка.</em>\nКак называется это стихотворение Б. Заходера?","choices":["«Дворник»","«Слесарь»","«Сапожник»","«Портной»","«Фокусник»."],"key":"Б","review":["Молоток и тиски","Посмотри, какие инструменты подходят для обработки деталей. Деталь можно зажать тисками, обработать напильником или распилить ножовкой.","Именно с такими инструментами работает слесарь. Поэтому стихотворение о слесаре, который к тому же ценит сноровку."]},{"author":"Л. Фёдорова","question":"Какое прилагательное образовано иначе, чем остальные?","choices":["<em>подвальный</em>","<em>подводный</em>","<em>подлёдный</em>","<em>подлунный</em>","все эти прилагательные образованы одним способом."],"key":"А","review":["Слова на «под-»","«Подводный» значит «под водой», «подлёдный» — «подо льдом», «подлунный» — «под луной». Проверь, куда ведёт похожая подсказка в четвёртом слове.","«Подвальный» значит «относящийся к подвалу». Его образовали, прибавив суффикс к целому названию помещения «подвал»."]},{"author":"И. Иткин","question":"Заполним пропуски. Какое предложение будет сильно отличаться от остальных?","choices":["<em>Лошадь ..., то есть говорит «...!»</em>","<em>Кошка ..., то есть говорит «...!»</em>","<em>Лягушка ..., то есть говорит «...!»</em>","<em>Петух ..., то есть говорит «...!»</em>","<em>Свинья ..., то есть говорит «...!»</em>"],"key":"А","review":["Звуки животных","Кошка мяукает — «мяу», лягушка квакает — «ква», петух кукарекает — «кукареку», свинья хрюкает — «хрю». Названия действий похожи на возгласы.","Лошадь ржёт — «и-го-го». В глаголе «ржёт» самого возгласа не слышно, поэтому это предложение отличается."]},{"author":"Л. Фёдорова","question":"<em>Лисе Алисе и коту Базилио удалось обвести Буратино вокруг</em> __________ <em>и</em> <em>заполучить его денежки</em>. Какое слово пропущено?","choices":["<em>столба</em>","<em>носа</em>","<em>сосны</em>","<em>хвоста</em>","<em>пальца.</em>"],"key":"Д","review":["Хитрость с Буратино","Лиса и кот обманули Буратино и забрали деньги. Подбери привычное выражение со смыслом «ловко обмануть».","Так говорят «обвести вокруг пальца». Его можно заменить словом «перехитрить»."]},{"author":"Б. Иомдин","question":"Какое из этих древнерусских слов ― название посуды?","choices":["<em>буда</em>","<em>лава</em>","<em>миса</em>","<em>пряга</em>","<em>соя.</em>"],"key":"В","review":["Древнерусское слово","Сравни древние слова с современными названиями посуды. К слову «миса» близко слово «миска».","В «миске» выделяется добавленное «-к-», как в уменьшительных словах. «Миса» была названием того же типа глубокой посуды."]},{"author":"И. Иткин","question":"Арабская пословица, означающая ‘прийти с ложью и небылицами’, буквально переводится на русский язык как <em>прийти ...</em>","choices":["<em>с ослиными рогами</em>","<em>с коровьим хвостом</em>","<em>с овечьим колокольчиком</em>","<em>с верблюжьим молоком</em>","<em>с петушиными перьями</em>."],"key":"А","review":["Арабская пословица","Ищи среди вариантов небылицу. У коровы бывает хвост, у верблюдицы — молоко, у петуха — перья, овце можно надеть колокольчик.","У осла рогов нет. Поэтому выражение «прийти с ослиными рогами» подходит к смыслу «прийти с выдумкой»."]},{"author":"Л. Фёдорова","question":"В каком предложении есть слово в дательном падеже?","choices":["<em>Маша по воду пошла.</em>","<em>Трава по пояс.</em>","<em>Кто в лес, кто по дрова.</em>","<em>Ветер по морю гуляет.</em>","<em>По-нашему говорила рыбка.</em>"],"key":"Г","review":["Слово после «по»","После «по» возможны разные падежи. В «по воду», «по пояс» и «по дрова» слова стоят в винительном, а «по-нашему» — целое наречие.","«Гуляет по чему?» — «по морю». Форма «морю» отвечает на вопрос дательного падежа."]},{"author":"Л. Фёдорова","question":"Во всех этих предложениях рассказывается о том, что уже произошло. Но одно можно понять и по-другому. Какое?","choices":["<em>Написали контрольную</em>.","<em>Поехали домой</em>.","<em>Встретили товарища</em>.","<em>Поиграли с котёнком</em>.","<em>Забыли ключи</em>."],"key":"Б","review":["Два смысла фразы","Прочитай «Поехали домой» как рассказ. Можно добавить «вчера мы» и получить сообщение о том, что уже было.","Теперь представь, что кто-то предлагает отправиться сейчас: «Поехали домой!» Остальные предложения в списке так обычно не используют."]},{"author":"Е. Бикмаев и К. Кноп","question":"Один иностранец, изучающий русский язык, образовывал прилагательные от названий месяцев, добавляя к названию месяца <em>-ский</em>. Сколько прилагательных он образовал правильно?","choices":["двенадцать","одиннадцать","десять","девять","восемь."],"key":"Г","review":["Прилагательные от месяцев","Попробуй буквально добавить «-ский». Получатся «январьский», «мартский» и «августский», но обычные формы — «январский», «мартовский», «августовский».","У остальных девяти месяцев название целиком сохраняется перед -ский. Например, «февраль» даёт «февральский», «май» — «майский», «сентябрь» — «сентябрьский». Значит, правильно образованы девять из двенадцати прилагательных."]},{"author":"Л. Фёдорова","question":"В сказке «Конёк-Горбунок» царь нанимает Иванушку-дурачка на службу во дворец; Иван вступает в переговоры:\n<em>То есть, я из огорода</em>\n<em>Стану царский воевода.</em>\n<em>Чудно дело! Так и быть,</em>\n<em>Стану, царь, тебе служить.</em>\n<em>Только, чур, со мной не драться</em>\n<em>И давать мне высыпаться,</em>\n<em>А не то <strong>я был таков</strong>!</em>\nЧто означает выделенное выражение?","choices":["я как был дураком, так им и останусь","я уже бывал воеводой","не видать тебе меня больше","буду бездельничать, как и раньше","я буду драться."],"key":"В","review":["Условия Иванушки","Иван соглашается служить, если его не будут бить и дадут высыпаться. Слова «а не то» вводят последствие нарушения этих условий.","«Я был таков» значит, что Иван быстро уйдёт и больше не покажется. Подходит «не видать тебе меня больше»."]},{"author":"И. Иткин","question":"Даны названия некоторых химических элементов и их латинские обозначения, разбитые на две группы:\nI: азот (N), кислород (O), железо (Fe), медь (Cu), кремний (1);\nII: бор (B), алюминий (Al), никель (Ni), криптон (2), калий (3).\nКакие обозначения должны стоять на месте цифр 1, 2 и 3? (Знания химии для решения задачи не требуется.)","choices":["Kr, K, Si","Kr, Si, K","Si, Kr, K","Si, K, Kr","K, Kr, Si."],"key":"В","review":["Символы элементов","Во второй группе B, Al и Ni передают начало слов «бор», «алюминий», «никель» латинскими буквами. Для «криптон» подходит Kr, а для «калий» — K.","Из вариантов остался Si для «кремния». Это подходит к первой группе, где данные символы не повторяют начало русского названия."]},{"author":"Е. Муравенко","question":"Однажды известный лингвист Д. Н. Шмелёв составил о своих сыновьях такой текст:\n<em>На вид ангел, на виадук Алеша шел. А куда Иван? …</em>\nКак заканчивается этот текст?","choices":["<em>Сел на диван.</em>","<em>Лег на диван.</em>","<em>Шел в ресторан.</em>","<em>Шел</em> <em>в кегельбан.</em>","<em>Уехал в Ливан</em>."],"key":"Б","review":["Текст об Алёше и Иване","Убери пробелы и знаки. Перед центром фразы есть «навиадук», а в обратную сторону это «кудаиван», как в вопросе «А куда Иван?».","Прочитай начало «навидангел» с конца. Получится «легнадиван». Тогда весь текст читается одинаково в обе стороны."]},{"author":"С. Переверзева","question":"Один из героев сказочной повести Ф. Кнорре «Капитан Крокус» — сыщик по фамилии Ктифф. А как его зовут?","choices":["Кики","Коко","Папа","Тити","Фуфу."],"key":"Г","review":["Имя сыщика Ктиффа","Сыщика ещё можно назвать детективом. Произнеси «детектив» вслух и послушай быстрые слоги.","Имя «Тити» вместе с фамилией «Ктифф» даёт «Тити Ктифф», это похоже по звучанию на «детектив». Варианты с другими гласными дальше от него."]},{"author":"Н. Добрушина","question":"В интернете гуляет такая шутка:\nте, кто изучает хороводы, ― <em>хороводоведы</em>;\nте, кто любит тех, кто изучает хороводы, ― <em>хороводоведофилы</em>;\nте, кто ненавидит тех, кто любит тех, кто изучает хороводы, ― <em>хороводоведофилофобы</em>;\nте, кто пожирает тех, кто ненавидит тех, кто любит тех, кто изучает хороводы, ― <em>хороводоведофилофобофаги</em>.\nКто такие <em>крокодилофилофагофобы</em>?","choices":["те, кто пожирает тех, кто ненавидит тех, кто любит крокодилов","те, кто любит тех, кто ненавидит тех, кто пожирает крокодилов","те, кто изучает тех, кто ненавидит тех, кто пожирает тех, кто любит крокодилов","те, кто ненавидит тех, кто пожирает тех, кто изучает крокодилов","те, кто ненавидит тех, кто пожирает тех, кто любит крокодилов."],"key":"Д","review":["Длинное шуточное слово","Разбери «крокодилофилофагофобы» слева направо. «Крокодилофилы» любят крокодилов, а «крокодилофилофаги» пожирают тех, кто их любит.","Последняя часть «-фобы» добавляет ещё одну группу, которая ненавидит этих пожирателей. Получается «ненавидят тех, кто пожирает тех, кто любит крокодилов»."]},{"author":"С. Бурлак","question":"По какому из этих географических названий можно без словаря однозначно определить, к какому роду оно относится?","choices":["<em>Свислочь</em>","<em>Сычуань</em>","<em>Улюколь</em>","<em>Ловать</em>","<em>Пльзень</em>."],"key":"А","review":["Род названия","Присмотрись к мягкому знаку после шипящей. В конце существительных в именительном падеже он указывает на женский род, как в слове «ночь».","Такой конец только у «Свислочь». После н, л и т мягкий знак встречается у слов обоих родов, поэтому другим названиям этой подсказки недостаточно."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
